using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 ulong pursuitFrame,exclusionFrame;int pursuitBudget;Godot.Collections.Array<Rid> pursuitExcluded;
 Godot.Collections.Array<Rid> PursuitExclusions(){ulong frame=Engine.GetPhysicsFrames();if(pursuitExcluded!=null&&exclusionFrame==frame)return pursuitExcluded;exclusionFrame=frame;var ids=new Godot.Collections.Array<Rid>();foreach(var enemy in infected)ids.Add(enemy.Body.GetRid());foreach(var friendly in communityAvatars.Values)ids.Add(friendly.Mover.Body.GetRid());foreach(var pair in MillPlayers())ids.Add(pair.Body.GetRid());return pursuitExcluded=ids;}
 bool PursuitClear(Vector3 from,Vector3 to,Godot.Collections.Array<Rid> excluded){var delta=to-from;delta.Y=0;if(delta.LengthSquared()<.01)return true;var side=delta.Normalized().Cross(Vector3.Up)*.42f;foreach(float offset in new[]{-1f,0f,1f}){var q=PhysicsRayQueryParameters3D.Create(from+Vector3.Up*.9f+side*offset,to+Vector3.Up*.9f+side*offset);q.Exclude=excluded;if(GetWorld3D().DirectSpaceState.IntersectRay(q).Count>0)return false;}return Math.Abs(to.Y-from.Y)<Math.Max(1.3,delta.Length()*.7);}
 List<Vector3> FindPursuitPath(Vector3 start,Vector3 goal,Godot.Collections.Array<Rid> excluded){const float step=1.5f;var origin=start;Vector3 Point((int X,int Z) p){float x=origin.X+p.X*step,z=origin.Z+p.Z*step;return dungeon==null?PursuitGround(x,z):new(x,start.Y,z);}var end=((int)Math.Round((goal.X-start.X)/step),(int)Math.Round((goal.Z-start.Z)/step));end=(Math.Clamp(end.Item1,-12,12),Math.Clamp(end.Item2,-12,12));var open=new PriorityQueue<(int,int),double>();var cost=new Dictionary<(int,int),double>{{(0,0),0}};var parents=new Dictionary<(int,int),(int,int)>();var closed=new HashSet<(int,int)>();open.Enqueue((0,0),0);(int,int) best=(0,0);double bestDistance=double.MaxValue;
  for(int expanded=0;open.Count>0&&expanded<180;expanded++){var p=open.Dequeue();if(!closed.Add(p))continue;double remaining=Math.Sqrt(Math.Pow(p.Item1-end.Item1,2)+Math.Pow(p.Item2-end.Item2,2));if(remaining<bestDistance){bestDistance=remaining;best=p;}if(remaining<1)break;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){if(x==0&&z==0)continue;var next=(p.Item1+x,p.Item2+z);if(Math.Abs(next.Item1)>12||Math.Abs(next.Item2)>12||closed.Contains(next))continue;double value=cost[p]+(x!=0&&z!=0?1.414:1);if(cost.TryGetValue(next,out double old)&&old<=value)continue;if(!PursuitClear(Point(p),Point(next),excluded))continue;cost[next]=value;parents[next]=p;open.Enqueue(next,value+Math.Sqrt(Math.Pow(next.Item1-end.Item1,2)+Math.Pow(next.Item2-end.Item2,2)));}}
  var result=new List<Vector3>();while(best!=(0,0)&&parents.TryGetValue(best,out var previous)){result.Add(Point(best));best=previous;}result.Reverse();return result;
 }
 Vector3 PursuitDirection(Infected e,Vector3 target,double dt){e.PathDue-=dt;var direct=target-e.Body.Position;direct.Y=0;if(direct.Length()<2)return direct;var excluded=PursuitExclusions();if(e.PathDue<=0){ulong frame=Engine.GetPhysicsFrames();if(frame!=pursuitFrame){pursuitFrame=frame;pursuitBudget=1;}if(pursuitBudget>0){pursuitBudget--;e.PathDue=1.1+Math.Abs(e.Home.X%5)*.07;e.Path=PursuitClear(e.Body.Position,target,excluded)?new():FindPursuitPath(e.Body.Position,target,excluded);e.PathTarget=target;}}
  while(e.Path.Count>0&&Distance(e.Body.Position,e.Path[0])<.65f)e.Path.RemoveAt(0);if(e.Path.Count>0){var direction=e.Path[0]-e.Body.Position;direction.Y=0;return direction;}return PursuitClear(e.Body.Position,target,excluded)?direct:Vector3.Zero;
 }
 void TickZombie(Infected e,double dt){e.Cooldown=Math.Max(0,e.Cooldown-dt);e.Stagger=Math.Max(0,e.Stagger-dt);float distance=Distance(e.Body.Position,player.Position);var npc=ZombieCommunityTarget(e,distance);if(npc!=null)distance=Distance(e.Body.Position,NpcPoint(npc));bool sees=npc!=null||Sight(e,distance);if(sees){e.Memory=8;e.Target=npc!=null?NpcPoint(npc):player.Position;}else e.Memory=Math.Max(0,e.Memory-dt);
  if(e.Stagger>0){e.AttackState="";e.AttackTime=0;e.Cooldown=Math.Max(.35,e.Cooldown);}
  if(e.AttackState!=""){e.AttackTime-=dt;if(e.AttackTime<=0){if(e.AttackState=="windup"){if(distance<1.9&&sees&&Math.Abs(e.Body.Position.Y-(npc?.Y??player.Position.Y))<1.3){if(npc!=null)HurtCommunity(npc,7+e.Tier*3);else game.Hurt(e.Tier);if(npc==null&&game.Life.Health<=0){Die();return;}}e.AttackState="recover";e.AttackTime=.65;e.Cooldown=1.2;}else e.AttackState="";}}
  else if(e.Stagger<=0&&e.Cooldown<=0&&distance<1.65&&sees){e.AttackState="windup";e.AttackTime=.6;}
  Vector3 target=e.Memory>0?e.Target:e.Home+new Vector3((float)Math.Sin(game.Clock*.08+e.Home.X)*5,0,(float)Math.Cos(game.Clock*.07+e.Home.Z)*5);var direction=e.Stagger<=0&&e.AttackState==""?PursuitDirection(e,target,dt):Vector3.Zero;float speed=(float)(e.Memory>0?(1.3+e.Tier*.18)*(game.Night?1.25:1)*(e.Night==1?1.5:1):.45);speed=InfectedSpeed(e,speed);var velocity=direction.Length()>.3f?direction.Normalized()*speed:Vector3.Zero;velocity.Y=e.Body.IsOnFloor()?-.1f:e.Body.Velocity.Y-18*(float)dt;e.Body.Velocity=velocity;e.Body.MoveAndSlide();if(dungeon==null&&e.Body.Position.Y<game.World.Height(e.Body.Position.X,e.Body.Position.Z)-10)e.Body.Position=Ground(e.Body.Position.X,e.Body.Position.Z);var facing=e.AttackState!=""?e.Target-e.Body.Position:direction;if(facing.LengthSquared()>.01)e.Body.Rotation=new(0,Mathf.Atan2(-facing.X,-facing.Z),0);AnimateCharacter(e);DamageBaseNear(e);
 }
 void ReactEnemyHit(Infected e,bool heavy){if(Species(e.Id)=="dog")AlertDogPack(e,player.Position);if(DormantWeeper(e)){e.BossState="weeper-windup";e.BossTime=1.2;e.BossAim=player.Position;e.Body.GetChild<CollisionShape3D>(0).Shape=new CapsuleShape3D{Radius=.4f,Height=2};e.Body.GetChild<CollisionShape3D>(0).Position=new(0,1,0);}if(IsCheckpointGuard(e.Id))StartCheckpointFight();e.Stagger=InfectedKind(e) is "bloater" or "bruiser"?.12:heavy?.75:.3;e.AttackState="";e.AttackTime=0;e.Cooldown=Math.Max(.35,e.Cooldown);e.Memory=8;e.Target=player.Position;}
}
